function cohesion(boid, boids) {
    const steer = new THREE.Vector3(0, 0, 0);
    let count = 0;

    for (const other of boids) {
        const d = boid.position.distanceTo(other.position);
        if (d > 0 && d < COHESION_DISTANCE) {
            steer.add(other.position);
            count++;
        }
    }

    if (count > 0) {
        steer.divideScalar(count);
        steer.sub(boid.position);
        steer.setLength(MAX_SPEED);
        steer.sub(boid.velocity);
        steer.clampLength(0, 0.05);
    }

    return steer;
}

function flee(boid) {
    const steer = new THREE.Vector3(0, 0, 0);
    const d = boid.position.distanceTo(threatPosition);

    if (d < THREAT_DISTANCE && d > 0) {
        const away = new THREE.Vector3().subVectors(boid.position, threatPosition);
        away.normalize();
        away.multiplyScalar(MAX_SPEED);
        away.sub(boid.velocity);
        away.clampLength(0, 0.3);
        return away;
    }

    return steer;
}

